    for (int i = 0; i < m + n - 1; i++) {
        int startRow = Math.max(0, i - n + 1);
        int startCol = Math.max(0, n - i - 1);
        int endRow = Math.min(m - 1, i);
        int endCol = Math.min(n - 1, i);
        for (int row = startRow; row <= endRow; row++) {
            result[index++] = mat[row][startCol + row];
        }
    }
